<?php
defined('BASEPATH') or exit('No direct script access allowed');
hooks()->add_filter('app_view_data','scaf_commission_view',60);
hooks()->add_action('app_admin_head','scaf_commission_assets',60);
function scaf_commission_assets(){if(strtolower(get_instance()->router->fetch_class())!=='commission')return;scaf_asset('assets/css/commission_workflows.css');scaf_asset('assets/js/commission_workflows.js');}
function scaf_commission_rank($rows){$groups=[];foreach($rows as $r){$currency=$r['currency_name']??'Unknown';$key=(int)($r['is_client']??0).':'.(int)$r['staffid'];if(!isset($groups[$currency][$key]))$groups[$currency][$key]=['staffid'=>(int)$r['staffid'],'is_client'=>(int)($r['is_client']??0),'amount'=>'0'];$groups[$currency][$key]['amount']=scaf_decimal_add($groups[$currency][$key]['amount'],$r['amount']);}foreach($groups as &$group){$group=array_values($group);usort($group,fn($a,$b)=>-scaf_decimal_cmp($a['amount'],$b['amount'])?:($a['staffid']<=>$b['staffid']));$group=array_slice($group,0,3);}unset($group);return $groups;}
function scaf_commission_snapshot($rows,$month){$items=[];$totals=[];foreach($rows as $row){if(substr($row['date'],0,7)!==$month||(int)$row['paid']===1)continue;$owed=scaf_decimal_sub($row['amount'],$row['amount_paid']??'0');if(scaf_decimal_cmp($owed,'0')<=0)continue;$c=$row['currency_name']??'Unknown';$items[(int)$row['id']]=['id'=>(int)$row['id'],'invoice_id'=>(int)$row['invoice_id'],'staffid'=>(int)$row['staffid'],'is_client'=>(int)($row['is_client']??0),'currency'=>$c,'date'=>$row['date'],'amount'=>scaf_decimal_normalize($row['amount']),'amount_paid'=>scaf_decimal_normalize($row['amount_paid']??'0'),'owed'=>$owed,'paid'=>(int)$row['paid']];$totals[$c]=scaf_decimal_add($totals[$c]??'0',$owed);}ksort($items);ksort($totals);$items=array_values($items);return ['month'=>$month,'items'=>$items,'totals'=>$totals,'hash'=>hash('sha256',json_encode([$month,$items],JSON_UNESCAPED_SLASHES))];}
function scaf_commission_transition($batch,$snapshot,$action,$staff,$now){
 if($action==='generate'){if($batch&&($batch['hash']??'')===$snapshot['hash'])return $batch;return $snapshot+['state'=>'pending_approval','generated_by'=>$staff,'generated_at'=>$now,'previous_approval'=>$batch&&($batch['state']??'')==='approved'?['hash'=>$batch['hash'],'approved_by'=>$batch['approved_by'],'approved_at'=>$batch['approved_at']]:($batch['previous_approval']??null)];}
 if($action!=='approve'||!$batch||($batch['hash']??'')!==$snapshot['hash'])throw new RuntimeException('Ledger changed. Generate and review a fresh batch.');
 if($batch['state']==='approved')return $batch;if($batch['state']!=='pending_approval')throw new RuntimeException('Batch is not ready for approval.');$batch['state']='approved';$batch['approved_by']=$staff;$batch['approved_at']=$now;return $batch;
}
function scaf_commission_month_valid($month){return is_string($month)&&preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$month)&&substr($month,0,4)>='1900'&&substr($month,0,4)<='2200';}
function scaf_commission_view($v){if(strtolower(get_instance()->router->fetch_class())!=='commission'||!in_array($v['path'],['smartchoice_report','commission/smartchoice_report'],true))return $v;$v['data']['leaders_by_currency']=scaf_commission_rank($v['data']['rows']??[]);$v['path']='../../modules/sc_admin_fixes/views/representatives/commission_report';return $v;}
function scaf_commission_row_tier($row){
 if(!function_exists('scaf_rep_policy')||!has_permission('sales_center','','view')||(int)($row['is_client']??0)===1)return null;
 static $cache=[];$id=(int)$row['staffid'];if(array_key_exists($id,$cache))return $cache[$id];$CI=&get_instance();if(!$CI->db->table_exists(db_prefix().'sales_center'))return null;
 $rep=$CI->db->where('staff_id',$id)->get(db_prefix().'sales_center')->row_array();if(!$rep)return $cache[$id]=null;
 $metrics=scaf_rep_metrics([$rep]);$attainment=scaf_rep_attainment($rep,$metrics['reps'][(int)$rep['id']]['closed']);return $cache[$id]=$attainment['tier']??null;
}
function scaf_commission_totals($rows){$g=[];foreach($rows as $r){$c=$r['currency_name']??'Unknown';if(!isset($g[$c]))$g[$c]=['earned'=>'0','paid'=>'0','owed'=>'0'];$paid=(string)($r['amount_paid']??((int)$r['paid']===1?$r['amount']:'0'));$g[$c]['earned']=scaf_decimal_add($g[$c]['earned'],$r['amount']);$g[$c]['paid']=scaf_decimal_add($g[$c]['paid'],$paid);$g[$c]['owed']=scaf_decimal_add($g[$c]['owed'],scaf_decimal_sub($r['amount'],$paid));}return $g;}
